/* Décomposeur de prime factorielle */
(function () {
  var svg = document.getElementById("fx-chart");
  if (!svg) return;
  var F = [
    {id:"fx-mkt",  name:{fr:"Marché",en:"Market",nl:"Markt"},    prem:5, col:"#12294a"},
    {id:"fx-val",  name:{fr:"Valeur",en:"Value",nl:"Value"},     prem:3, col:"#c19a3e"},
    {id:"fx-size", name:{fr:"Taille",en:"Size",nl:"Omvang"},     prem:2, col:"#2f8f83"},
    {id:"fx-mom",  name:{fr:"Momentum",en:"Momentum",nl:"Momentum"}, prem:4, col:"#b5652f"},
    {id:"fx-qual", name:{fr:"Qualité",en:"Quality",nl:"Kwaliteit"},  prem:3, col:"#6a5a8f"}
  ];
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function activeLang(){ return document.body.getAttribute("data-active-lang") || "fr"; }

  function draw() {
    var L=activeLang(), total=0, contribs=[];
    F.forEach(function(f){ var b=v(f.id); setT(f.id+"-o", b.toFixed(2)); var c=b*f.prem; total+=c; contribs.push({name:f.name[L], c:c, col:f.col}); });
    setT("fx-total", (total>=0?"+":"")+total.toFixed(2)+"%");

    var W=520,H=190,padL=88,padR=54,T=10, rowH=(H-2*T)/F.length;
    var maxAbs=0.0001; contribs.forEach(function(x){ if(Math.abs(x.c)>maxAbs) maxAbs=Math.abs(x.c); });
    var x0=padL + (W-padL-padR)*0.18; // zero axis (leaves room on left for small negatives)
    var scale=(W-padR-x0)/maxAbs;
    var g="";
    // zero axis
    g+='<line x1="'+x0+'" y1="'+T+'" x2="'+x0+'" y2="'+(H-T)+'" stroke="var(--ink-mute)" stroke-width="1.3"/>';
    contribs.forEach(function(x,i){
      var cy=T+i*rowH+rowH/2, bh=Math.min(rowH-12,20);
      var w=x.c*scale;
      var rx = x.c>=0 ? x0 : x0+w;
      g+='<text x="'+(padL-8)+'" y="'+(cy+4)+'" text-anchor="end" fill="var(--ink-soft)" font-size="12" font-weight="600" font-family="var(--sans)">'+x.name+'</text>';
      g+='<rect x="'+rx.toFixed(1)+'" y="'+(cy-bh/2)+'" width="'+Math.abs(w).toFixed(1)+'" height="'+bh+'" fill="'+(x.c>=0?x.col:"#9aa3b0")+'"/>';
      var tx = x.c>=0 ? x0+w+5 : x0+w-5;
      g+='<text x="'+tx.toFixed(1)+'" y="'+(cy+4)+'" text-anchor="'+(x.c>=0?"start":"end")+'" fill="var(--ink-soft)" font-size="11" font-family="var(--mono)">'+(x.c>=0?"+":"")+x.c.toFixed(2)+'</text>';
    });
    svg.innerHTML=g;
  }

  F.forEach(function(f){ var e=document.getElementById(f.id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
